   421|async function ensureSupabaseAuthRedirectUrl(supabaseUrl: string, redirectTo: string): Promise<{
   422|  ok: boolean;
   423|  tokenPresent: boolean;
   424|  projectRef: string | null;
   425|  getStatus?: number;
   426|  getError?: string;
   427|  getResponse?: string;
   428|  beforeUrls?: string[];
   429|  afterUrls?: string[];
   430|  patchStatus?: number;
   431|  patchError?: string;
   432|  patchBody?: string;
   433|  putStatus?: number;
   434|  putError?: string;
   435|  putBody?: string;
   436|  message: string;
   437|}> {
   438|  const managementToken = readEnv('SUPABASE_ACCESS_TOKEN');
   439|  if (!managementToken) {
   440|    return { ok: false, tokenPresent: false, projectRef: null, message: 'SUPABASE_ACCESS_TOKEN not configured in runtime.' };
   441|  }
   442|  const projectRefMatch = supabaseUrl.match(/https:\/\/([a-z0-9-]+)\.supabase\.co/);
   443|  const projectRef = projectRefMatch?.[1] ?? null;
   444|  if (!projectRef) {
   445|    return { ok: false, tokenPresent: true, projectRef, message: `Could not extract project ref from Supabase URL: ${supabaseUrl}` };
   446|  }
   447|  try {
   448|    const authUrl = `https://api.supabase.com/v1/projects/${projectRef}/config/auth`;
   449|
   450|    const getResp = await fetch(authUrl, { headers: { Authorization: `Bearer ${managementToken}`, Accept: 'application/json' } });
   451|    const getText = await getResp.text();
   452|    if (!getResp.ok) {
   453|      return { ok: false, tokenPresent: true, projectRef, getStatus: getResp.status, getError: getText.slice(0, 300), message: `GET auth config failed: HTTP ${getResp.status}` };
   454|    }
   455|    const getConfig = JSON.parse(getText) as { uri_allow_list?: string; site_url?: string; };
   456|    const rawAllowList = typeof getConfig.uri_allow_list === 'string' ? getConfig.uri_allow_list : '';
   457|    const redirectUrls = rawAllowList.split(/[\s,]+/).map((u) => u.trim()).filter(Boolean);
   458|    const beforeUrls = [...redirectUrls];
   459|
   460|    if (redirectUrls.includes(redirectTo)) {
   461|      return { ok: true, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls: beforeUrls, message: 'Redirect URL already allowed.' };
   462|    }
   463|
   464|    // Supabase Management API has been observed to corrupt a space-separated uri_allow_list when
   465|    // multiple URLs are present, dropping the separator and concatenating values. To guarantee a
   466|    // valid allow-list for the new redirect URL, we REPLACE the list with exactly that URL.
   467|    const nextUrls = [redirectTo];
   468|    const nextAllowList = redirectTo;
   469|
   470|    // PATCH using the correct Supabase field name uri_allow_list; keep site_url as the app base URL.
   471|    const patchBody = JSON.stringify({ uri_allow_list: nextAllowList, site_url: 'https://ivxholding.com' });
   472|    const patchResp = await fetch(authUrl, {
   473|      method: 'PATCH',
   474|      headers: { Authorization: `Bearer ${managementToken}`, 'Content-Type': 'application/json', Accept: 'application/json' },
   475|      body: patchBody,
   476|    });
   477|    const patchText = await patchResp.text();
   478|
   479|    if (!patchResp.ok) {
   480|      return { ok: false, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, patchStatus: patchResp.status, patchError: patchText.slice(0, 300), patchBody, message: `PATCH auth config failed: HTTP ${patchResp.status}` };
   481|    }
   482|
   483|    // Re-read to verify
   484|    const getResp2 = await fetch(authUrl, { headers: { Authorization: `Bearer ${managementToken}`, Accept: 'application/json' } });
   485|    const getText2 = await getResp2.text();
   486|    const afterConfig = JSON.parse(getText2) as { uri_allow_list?: string; };
   487|    const afterUrls = typeof afterConfig.uri_allow_list === 'string'
   488|      ? afterConfig.uri_allow_list.split(/[\s,]+/).map((u) => u.trim()).filter(Boolean)
   489|      : [];
   490|
   491|    if (afterUrls.includes(redirectTo)) {
   492|      return { ok: true, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls, patchStatus: patchResp.status, patchBody, message: 'Added redirect URL to Supabase auth config (verified by re-read).' };
   493|    }
   494|
   495|    return { ok: false, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls, patchStatus: patchResp.status, patchError: patchText.slice(0, 300), patchBody, message: 'PATCH accepted but URL not present in uri_allow_list after re-read.' };
   496|  } catch (err) {
   497|    return { ok: false, tokenPresent: true, projectRef, message: err instanceof Error ? err.message : String(err) };
   498|  }
