   536|async function updateSupabaseAuthConfig(input: Record<string, unknown>): Promise<Record<string, unknown>> {
   537|  const managementToken = readEnv('SUPABASE_ACCESS_TOKEN');
   538|  const supabaseUrl = readEnv('EXPO_PUBLIC_SUPABASE_URL') || readEnv('SUPABASE_URL');
