   548|    return { ok: false, message: `Could not extract project ref from Supabase URL: ${supabaseUrl}` };
   549|  }
   550|  const patchBody: Record<string, unknown> = {};
   551|  if (input.mailer_autoconfirm === true || input.mailer_autoconfirm === 'true') {
   552|    patchBody.mailer_autoconfirm = true;
   553|  }
   554|  if (input.mailer_autoconfirm === false || input.mailer_autoconfirm === 'false') {
