   563|  const smtpFields = ['smtp_host', 'smtp_port', 'smtp_user', 'smtp_pass', 'smtp_admin_email', 'smtp_sender_name', 'smtp_max_frequency'];
   564|  for (const field of smtpFields) {
   565|    if (field in input) {
   566|      const value = input[field];
   567|      if (field === 'smtp_max_frequency') {
   568|        const num = Number(value);
   569|        if (Number.isFinite(num) && num > 0) {
