   579|  if (Object.keys(patchBody).length === 0) {
   580|    return { ok: false, message: 'No valid config fields to update. Supported: mailer_autoconfirm, enable_signup, smtp_host, smtp_port, smtp_user, smtp_pass, smtp_admin_email, smtp_sender_name, smtp_max_frequency.' };
   581|  }
