   595|    const getText = await getResp.text();
   596|    const afterConfig = JSON.parse(getText) as Record<string, unknown>;
   597|    return {
   598|      ok: true,
   599|      projectRef,
   600|      patchStatus: patchResp.status,
   601|      patchBody: Object.fromEntries(Object.entries(patchBody).map(([k, v]) => [k, typeof v === 'string' && k === 'smtp_pass' ? '[redacted]' : v])),
   602|      afterMailerAutoconfirm: afterConfig.mailer_autoconfirm,
