   605|      afterSmtpPort: afterConfig.smtp_port,
   606|      afterSmtpUser: afterConfig.smtp_user ? '[redacted]' : null,
   607|      afterSmtpSenderName: afterConfig.smtp_sender_name,
   608|      afterSmtpAdminEmail: afterConfig.smtp_admin_email,
   609|      message: 'Supabase auth config updated successfully.',
