   342|async function pollRenderDeploy(apiKey: string, serviceId: string, deployId: string, maxMs: number): Promise<{ entry: RenderDeployStatusEntry | null; pollCount: number; terminal: boolean }> {
   343|  const deadline = Date.now() + maxMs;
   344|  let pollCount = 0;
   345|  let entry: RenderDeployStatusEntry | null = null;
   346|  while (Date.now() < deadline) {
   347|    pollCount += 1;
   348|    try {
   349|      const r = await fetch(`https://api.render.com/v1/services/${encodeURIComponent(serviceId)}/deploys/${encodeURIComponent(deployId)}`, {
   350|        headers: { Authorization: `Bearer ${apiKey}`, Accept: 'application/json' },
   351|      });
   352|      if (r.ok) {
   353|        const data = await r.json().catch(() => null) as RenderDeployStatusEntry | null;
   354|        if (data) entry = data;
   355|        const status = String((data?.status ?? '')).toLowerCase();
   356|        const terminalStates = ['live', 'deactivated', 'build_failed', 'update_failed', 'canceled', 'pre_deploy_failed'];
   357|        if (terminalStates.some((s) => status.includes(s))) return { entry, pollCount, terminal: true };
   358|      }
   359|    } catch {
   360|      // network blip — keep polling
   361|    }
   362|    await new Promise((res) => setTimeout(res, 5000));
